public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    if(_fieldId == fieldNum(LeavePlanTier, NVBaseLeaves)
        || _fieldId == fieldNum(LeavePlanTier, NVAdditionalLeaves))
    {
        this.AccrualAmount = this.NVBaseLeaves + this.NVAdditionalLeaves;
    }
}
